using ull = uint64_t;
struct BitVec {
	vec<pair<ull, int>> b;
	BitVec(const vec<bool>& a): b(sz(a) / 64 + 1) {
		rep(i,0,sz(a)) {
			auto& [x, y] = b[i >> 6];
			x |= ull(a[i]) << (i & 63), y += a[i];
		}
		rep(i,1,sz(b)) b[i].second += b[i - 1].second;
	}
	int rank(int r) {
		auto [x, y] = b[r >> 6];
		return y - popcount(x & -1ULL << (r & 63));
	}
};

auto compress_coords(auto &X) {
	vi values;
	values.reserve(sz(X));
	sort(all(X));
	int i = -1, prev;
	for (auto &x : X) {
		if (i == -1 || x != prev) {
			i++;
			prev = x;
			values.pb(x);
		}
		x.get() = i;
	}
	return values;
}

struct FT2 {
	vec<vi> ys; vec<vec<ll>> ft;
	FT2(int lim_x) : ys(lim_x) {}
	void fakeUpdate(int x, int y) {
		for (; x < sz(ys); x |= x + 1) ys[x].push_back(y);
	}
	void init() {
		for (vi& v : ys) sort(all(v)), ft.emplace_back(sz(v));
	}
	int ind(int x, int y) {
		return int(lower_bound(all(ys[x]), y) - ys[x].begin());
	}
	void update(int x, int y, ll dif) {
		for (; x < sz(ys); x |= x + 1)
			for (int i = ind(x, y); i < sz(ft[x]); i |= i + 1)
				ft[x][i] += dif;
	}
	ll query(int x, int y) {
		ll sum = 0;
		for (; x; x &= x - 1)
			for (int i = ind(x - 1, y); i; i &= i - 1)
				sum += ft[x - 1][i - 1];
		return sum;
	}
};

struct Line {
	mutable ll k, m, p;
	bool operator<(const Line &o) const { return k < o.k; }
	bool operator<(ll x) const { return p < x; }
};
struct LineContainer : multiset<Line, less<>> {
	static const ll inf = LLONG_MAX;
	ll div(ll a, ll b) {
		return a / b - ((a ^ b) < 0 && a % b);
	}
	bool isect(iterator x, iterator y) {
		if (y == end())
			return x->p = inf, 0;
		if (x->k == y->k)
			x->p = x->m > y->m ? inf : -inf;
		else
			x->p = div(y->m - x->m, x->k - y->k);
		return x->p >= y->p;
	}
	void add(ll k, ll m) {
		auto z = insert({k, m, 0}), y = z++, x = y;
		while (isect(y, z))
			z = erase(z);
		if (x != begin() && isect(--x, y))
			isect(x, y = erase(y));
		while ((y = x) != begin() && (--x)->p >= y->p)
			isect(x, erase(y));
	}
	ll query(ll x) {
		auto l = *lower_bound(x);
		return l.k * x + l.m;
	}
};

struct FT {
	vec<ll> s;
	FT(int n) : s(n) {}
	void update(int pos, ll dif) {
		for (; pos < sz(s); pos |= pos + 1) s[pos] += dif;
	}
	ll query(int pos) {
		ll res = 0;
		for (; pos > 0; pos &= pos - 1) res += s[pos - 1];
		return res;
	}
	int lower_bound(ll sum) {
		int pos = 0;
		for (int pw = 1 << 25; pw; pw >>= 1) {
			if (pos + pw <= sz(s) && s[pos + pw - 1] < sum)
				pos += pw, sum -= s[pos - 1];
		}
		return pos;
	}
};

