void add(int ind, int end);
void del(int ind, int end);
int calc();
vi mo(vec<pii>& Q) {
	int L = 0, R = 0, blk = 350;
	vi s(sz(Q)), res = s;
#define K(x) pii{x[0]/blk, x[1] ^ -(x[0]/blk & 1)}
	iota(all(s), 0);
	sort(all(s), [&](int s, int t){ return K(Q[s]) < K(Q[t]); });
	for (int qi : s) {
		auto q = Q[qi];
		while (L > q[0]) add(--L, 0);
		while (R < q[1]) add(R++, 1);
		while (L < q[0]) del(L++, 0);
		while (R > q[1]) del(--R, 1);
		res[qi] = calc();
	}
#undef K
	return res;
}
vi moTree(vec<pii>& Q, vec<vi>& ed, int root=0){
	int N = sz(ed), pos[2] = {}, blk = 350;
	vi s(sz(Q)), res = s, I(N), L(N), R(N), in(N), par(N);
	add(0, 0), in[0] = 1;
	auto dfs = [&](int x, int p, int dep, auto& f) -> void {
		par[x] = p;
		L[x] = N;
		if (dep) I[x] = N++;
		for (int y : ed[x]) if (y != p) f(y, x, !dep, f);
		if (!dep) I[x] = N++;
		R[x] = N;
	};
	dfs(root, -1, 0, dfs);
#define K(x) pii{I[x[0]] / blk, I[x[1]] ^ -(I[x[0]] / blk & 1)}
	iota(all(s), 0);
	sort(all(s), [&](int s, int t){ return K(Q[s]) < K(Q[t]); });
	for (int qi : s) rep(end,0,2) {
		int &a = pos[end], b = Q[qi][end], i = 0;
#define step(c) { if (in[c]) { del(a, end); in[a] = 0; } \
									else { add(c, end); in[c] = 1; } a = c; }
		while (!(L[b] <= L[a] && R[a] <= R[b]))
			I[i++] = b, b = par[b];
		while (a != b) step(par[a]);
		while (i--) step(I[i]);
		if (end) res[qi] = calc();
	}
#undef K
#undef step
	return res;
}

#include <bits/extc++.h>
using namespace __gnu_pbds;
template <class T>
using Tree = tree<T, null_type, less<T>, rb_tree_tag,
									tree_order_statistics_node_update>;

struct SeqTree : SplayTree {
	int root = 0;
	SeqTree(int n, const vec<ll>& a = {}) : SplayTree(n + 2) {
		rep(i, 0, sz(a)) T[i + 2].self = a[i];
		rep(i, 1, n + 2) set(i + 1, 0, i);
		splay(root = n + 2);
	}
	SeqTree(const vec<ll>& a) : SeqTree(sz(a), a) {}
	int kth(int k, int x = 0) {
		for (x = x ?: root; ; ) {
			push(x);
			int l = T[x].ch[0], s = T[l].sz;
			if (k < s) x = l;
			else if (k == s) return splay(x), root = x;
			else k -= s + 1, x = T[x].ch[1];
		}
	}
	int node(int l, int r) {
		int L = kth(l), R = kth(r + 1);
		splay(root = L); splay(R, L);
		return T[R].ch[0];
	}
	void reverse(int l, int r) {
		if (l < r) T[node(l, r)].flip ^= 1;
	}
	ll query(int l, int r) {
		return l >= r ? 0 : T[node(l, r)].path;
	}
};

template <class T> struct SparseTable {
	vec<vec<T>> jmp;
	SparseTable(vec<T> &a) : jmp(1, vec<T>(sz(a))) {
		rep(i,0,sz(a))
			jmp[0][i] = a[i];
		for (int pw = 1, k = 1; pw * 2 <= sz(a); pw *= 2, ++k) {
			jmp.emplace_back(sz(a) - pw * 2 + 1);
			rep(j,0,sz(jmp[k]))
				jmp[k][j] = min(jmp[k - 1][j], jmp[k - 1][j + pw]);
		}
	}
	T query(int b, int e) {
		int dep = 31 - __builtin_clz(e - b);
		return min(jmp[dep][b], jmp[dep][e - (1 << dep)]);
	}
};

struct SplayTree {
	struct Node {
		int ch[2] = {0, 0}, p = 0, sz = 1;
		ll self = 0, path = 0;
		ll sub = 0, vir = 0;
		bool flip = 0;
	};
	vec<Node> T;
	SplayTree(int n) : T(n + 1) { T[0].sz = 0; }
	void push(int x) {
		if (!x || !T[x].flip) return;
		int l = T[x].ch[0], r = T[x].ch[1];
		T[l].flip ^= 1, T[r].flip ^= 1;
		swap(T[x].ch[0], T[x].ch[1]);
		T[x].flip = 0;
	}
	void pull(int x) {
		int l = T[x].ch[0], r = T[x].ch[1]; push(l); push(r);
		T[x].sz = 1 + T[l].sz + T[r].sz;
		T[x].path = T[l].path + T[x].self + T[r].path;
		T[x].sub = T[x].vir + T[l].sub + T[r].sub + T[x].self;
	}
	void set(int x, int d, int y) {
		T[x].ch[d] = y; T[y].p = x; pull(x);
	}
	int dir(int x) {
		int p = T[x].p; if (!p) return -1;
		return T[p].ch[0] == x ? 0 : T[p].ch[1] == x ? 1 : -1;
	}
	void rotate(int x) {
		int y = T[x].p, z = T[y].p, dx = dir(x), dy = dir(y);
		set(y, dx, T[x].ch[!dx]);
		set(x, !dx, y);
		if (~dy) set(z, dy, x);
		T[x].p = z;
	}
	void splay(int x, int goal = 0) {
		for (push(x); ~dir(x) && T[x].p != goal; ) {
			int y = T[x].p, z = T[y].p;
			push(z); push(y); push(x);
			int dx = dir(x), dy = dir(y);
			if (~dy && z != goal) rotate(dx != dy ? x : y);
			rotate(x);
		}
	}
};

template <class T, auto op> struct SegmentTree {
	int n; T e; vec<T> s;
	SegmentTree(int n, T e) : n(n), e(e), s(2*n, e) {}
	T query(int a, int b) {
		T ra = e, rb = e;
		for (a += n, b += n; a < b; a /= 2, b /= 2) {
			if (a % 2) ra = op(ra, s[a++]);
			if (b % 2) rb = op(s[--b], rb);
		}
		return op(ra, rb);
	}
	void upd(int i, T u) {
		for (i += n, s[i] = u; i /= 2;)
			s[i] = op(s[i*2], s[i*2+1]);
	}
	void build(vec<T> &a) {
		rep(i,0,n) s[i + n] = a[i];
		for (int i = n - 1; i >= 0; i--)
			s[i] = op(s[i*2], s[i*2+1]);
	}
};

template <class T, auto op, class U> struct SegmentTree {
	int n; T e; U id; vec<T> s; vec<U> lz;
	SegmentTree(int n, T e, U id)
		: n(n), e(e), id(id), s(2*n, e), lz(n, id) {}
	T query(int l, int r) { return query(l, r, 1, 0, n); }
	T query(int l, int r, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return e;
		if (l <= tl && tr <= r) return s[v];
		push(v, tl, tr);
		int tm = split(tl, tr);
		return op(query(l, r, 2*v, tl, tm),
							query(l, r, 2*v+1, tm, tr));
	}
	void upd(int l, int r, U u) { return upd(l, r, u, 1, 0, n); }
	void upd(int l, int r, U u, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return;
		if (l <= tl && tr <= r) {
			s[v] = u.map(s[v], tl, tr);
			if (v < n) lz[v] = lz[v](u);
			return;
		}
		push(v, tl, tr);
		int tm = split(tl, tr);
		upd(l, r, u, 2*v, tl, tm), upd(l, r, u, 2*v+1, tm, tr);
		s[v] = op(s[2*v], s[2*v+1]);
	}
	void push(int v, int tl, int tr) {
		int tm = split(tl, tr);
		upd(tl, tm, lz[v], 2*v, tl, tm);
		upd(tm, tr, lz[v], 2*v+1, tm, tr);
		lz[v] = id;
	}
	void build(vec<T>& a) {
		auto pw2 = bit_ceil(size(a));
		rep(i,0,n) s[(i + pw2) % n + n] = a[i];
		for (int i = n - 1; i >= 1; i--) s[i] = op(s[2*i], s[2*i+1]);
	}
};

template <class T, auto op, class U> struct SegmentTree {
	struct Node {
		int l = 0, r = 0;
		T x;
		U lz;
	};
	int n; T e; U id;
	vec<Node> s;
	SegmentTree(int n, T e, U id)
		: n(n), e(e), id(id), s(1, {0, 0, e, id}) {}
	int copy(int v) {
		s.emplace_back(s[v]);
		return sz(s) - 1;
	};
	T query(int l, int r, int v) { return query(l, r, v, 0, n); }
	T query(int l, int r, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return e;
		if (l <= tl && tr <= r) return s[v].x;
		int t = sz(s);
		v = push(v, tl, tr);
		int tm = (tl+tr)/2;
		T val = op(query(l, r, s[v].l, tl, tm),
							 query(l, r, s[v].r, tm, tr));
		s.resize(t);
		return val;
	}
	int upd(int l, int r, U u, int v) {
		return upd(l, r, u, v, 0, n);
	}
	int upd(int l, int r, U u, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return v;
		if (l <= tl && tr <= r) {
			v = copy(v);
			s[v].x = u.map(s[v].x, tl, tr);
			s[v].lz = s[v].lz(u);
		} else {
			v = push(v, tl, tr);
			int tm = (tl+tr)/2;
			s[v].l = upd(l, r, u, s[v].l, tl, tm);
			s[v].r = upd(l, r, u, s[v].r, tm, tr);
			s[v].x = op(s[s[v].l].x, s[s[v].r].x);
		}
		return v;
	}
	int push(int v, int tl, int tr) {
		v = copy(v);
		if (tr - tl == 1) return v;
		int tm = (tl+tr)/2;
		s[v].l = upd(tl, tm, s[v].lz, s[v].l, tl, tm);
		s[v].r = upd(tm, tr, s[v].lz, s[v].r, tm, tr);
		s[v].lz = id;
		return v;
	}
};

template <class T, auto op> struct SegmentTree {
	struct Node {
		int l = 0, r = 0;
		T x;
	};
	int n; T e;
	vec<Node> s;
	SegmentTree(int n, T e) : n(n), e(e), s(1, {0, 0, e}) {}
	int copy(int v) {
		s.emplace_back(s[v]);
		return sz(s) - 1;
	};
	T query(int l, int r, int v) { return query(l, r, v, 0, n); }
	T query(int l, int r, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return e;
		if (l <= tl && tr <= r) return s[v].x;
		int tm = (tl+tr)/2;
		return op(query(l, r, s[v].l, tl, tm),
							query(l, r, s[v].r, tm, tr));
	}
	int upd(int pos, T u, int v) { return upd(pos, u, v, 0, n); }
	int upd(int pos, T u, int v, int tl, int tr) {
		v = copy(v);
		if (tr - tl == 1) {
			s[v].x = u;
		} else {
			int tm = (tl+tr)/2;
			if (pos < tm) s[v].l = upd(pos, u, s[v].l, tl, tm);
			else s[v].r = upd(pos, u, s[v].r, tm, tr);
			s[v].x = op(s[s[v].l].x, s[s[v].r].x);
		}
		return v;
	}
};

template <class T, auto op> struct SegmentTree {
	int n; T e; vec<T> s;
	SegmentTree(int n, T e) : n(n), e(e), s(2*n, e) {}
	T query(int l, int r) { return query(l, r, 1, 0, n); }
	T query(int l, int r, int v, int tl, int tr) {
		if (r <= tl || tr <= l) return e;
		if (l <= tl && tr <= r) return s[v];
		int tm = split(tl, tr);
		return op(query(l, r, 2*v, tl, tm),
							query(l, r, 2*v+1, tm, tr));
	}
	void upd(int pos, T u) { return upd(pos, u, 1, 0, n); }
	void upd(int pos, T u, int v, int tl, int tr) {
		if (tr - tl == 1) {
			s[v] = u;
		} else {
			int tm = split(tl, tr);
			if (pos < tm) upd(pos, u, 2*v, tl, tm);
			else upd(pos, u, 2*v+1, tm, tr);
			s[v] = op(s[2*v], s[2*v+1]);
		}
	}
	void build(vec<T>& a) {
		auto pw2 = bit_ceil(size(a));
		rep(i,0,n) s[(i + pw2) % n + n] = a[i];
		for (int i = n - 1; i >= 1; i--) s[i] = op(s[2*i], s[2*i+1]);
	}
};

int split(int tl, int tr) {
	int pw2 = 1 << __lg(tr - tl);
	return min(tl + pw2, tr - pw2 / 2);
}

struct Tag {
	ll b = 1, c = 0;
	ll map(ll x, int l, int r) const {
		return (x * b % mod + c * (r - l) % mod) % mod;
	}
	Tag operator()(Tag nu) const {
		return {
			b * nu.b % mod,
			(c * nu.b + nu.c) % mod
		};
	}
};

template <class T> struct Treap {
	T* root = 0;
	deque<T> s;
	template <class V>
	T* make_node(V x) {
		s.emplace_back(x);
		return &s.back();
	}
	int cnt(T* v) {
		return v ? v->c : 0;
	}
	pair<T*, T*> split(T* v, int k) {
		if (!v) return {};
		v->push();
		if (cnt(v->l) >= k) {
			auto [L, R] = split(v->l, k);
			v->l = R;
			return {L, v->pull()};
		} else {
			auto [L, R] = split(v->r, k - cnt(v->l) - 1);
			v->r = L;
			return {v->pull(), R};
		}
	}
	T* merge(T* l, T* r) {
		if (!l || !r) return l ? l : r;
		l->push(), r->push();
		if (l->y > r->y) {
			l->r = merge(l->r, r);
			return l->pull();
		} else {
			r->l = merge(l, r->l);
			return r->pull();
		}
	}
	void insert(T* v, int k) {
		auto [L, R] = split(root, k);
		root = merge(merge(L, v), R);
	}
};

mt19937 rng(chrono::high_resolution_clock::now()
						.time_since_epoch().count());
struct Node {
	Node *l = 0, *r = 0;
	int y, c = 1;
	ll x;
	Node(ll x) : y(int(rng())), x(x) {}
	Node* pull() {
		c = 1;
		if (l) c += l->c;
		if (r) c += r->c;
		return this;
	}
	void push() {}
};

struct UnionFind {
	vi e;
	UnionFind(int n) : e(n, -1) {}
	bool same(int a, int b) { return find(a) == find(b); }
	int size(int x) { return -e[find(x)]; }
	int find(int x) {
		return e[x] < 0 ? x : e[x] = find(e[x]);
	}
	bool join(int a, int b) {
		a = find(a), b = find(b);
		if (a == b)
			return false;
		if (e[a] > e[b])
			swap(a, b);
		e[a] += e[b];
		e[b] = a;
		return true;
	}
};

struct RollbackUF {
	vi e; vec<pii> st;
	RollbackUF(int n) : e(n, -1) {}
	int size(int x) { return -e[find(x)]; }
	int find(int x) { return e[x] < 0 ? x : find(e[x]); }
	int time() { return sz(st); }
	void rollback(int t) {
		for (int i = time(); i --> t;)
			e[st[i][0]] = st[i][1];
		st.resize(t);
	}
	bool join(int a, int b) {
		a = find(a), b = find(b);
		if (a == b) return false;
		if (e[a] > e[b]) swap(a, b);
		st.push_back({a, e[a]});
		st.push_back({b, e[b]});
		e[a] += e[b]; e[b] = a;
		return true;
	}
};

struct Wavelet {
	int n;
	vec<BitVec> bv;
	Wavelet(vec<ull> a, ull sigma) :
		n(sz(a)), bv(bit_width(sigma), {{}}) {
		for (int h = sz(bv); h--;) {
			int i = 0;
			vec<bool> b(n);
			ranges::stable_partition(a,
				[&](ull x) { return b[i++] = (~x >> h) & 1; });
			bv[h] = b;
		}
	}
	ull kth(int l, int r, int k) {
		ll res = 0;
		for (int h = sz(bv); h--;) {
			int l0 = bv[h].rank(l), r0 = bv[h].rank(r);
			if (k < r0 - l0) l = l0, r = r0;
			else
				k -= r0 - l0, res |= 1ULL << h,
					l += bv[h].rank(n) - l0, r += bv[h].rank(n) - r0;
		}
		return res;
	}
	int count(int l, int r, ull ub) {
		int res = 0;
		for (int h = sz(bv); h--;) {
			int l0 = bv[h].rank(l), r0 = bv[h].rank(r);
			if ((~ub >> h) & 1) l = l0, r = r0;
			else
				res += r0 - l0, l += bv[h].rank(n) - l0,
					r += bv[h].rank(n) - r0;
		}
		return res;
	}
};

vi blossom(vec<vi>& adj) {
	int n = sz(adj), T = -1;
	vi mate(n, -1), label(n), par(n), orig(n), aux(n, -1), q;
	auto lca = [&](int x, int y) {
		for (T++; ; swap(x, y)) {
			if (x == -1) continue;
			if (aux[x] == T) return x;
			aux[x] = T;
			x = (mate[x] == -1 ? -1 : orig[par[mate[x]]]);
		}
	};
	auto blossom = [&](int v, int w, int a) {
		while (orig[v] != a) {
			par[v] = w, w = mate[v];
			if (label[w] == 1) label[w] = 0, q.pb(w);
			orig[v] = orig[w] = a, v = par[w];
		}
	};
	auto augment = [&](int v) {
		while (v != -1) {
			int pv = par[v], nv = mate[pv];
			mate[v] = pv, mate[pv] = v, v = nv;
		}
	};
	auto bfs = [&](int root) {
		fill(all(label), -1), iota(all(orig), 0);
		q.clear(), q.pb(root), label[root] = 0;
		rep(i,0,sz(q)) {
			int v = q[i];
			for (auto x : adj[v]) if (label[x] == -1) {
				label[x] = 1, par[x] = v;
				if (mate[x] == -1) return augment(x);
				label[mate[x]] = 0, q.pb(mate[x]);
			} else if (label[x] == 0 && orig[v] != orig[x]) {
				int a = lca(orig[v], orig[x]);
				blossom(x, v, a), blossom(v, x, a);
			}
		}
	};
	rep(i,0,n) if (mate[i] == -1) bfs(i);
	return mate;
}

struct Dinic {
	struct Edge {
		int to, rev;
		ll c, oc;
		ll flow() { return max(oc - c, ll(0)); }
	};
	vi lvl, ptr, q;
	vec<vec<Edge>> g;
	Dinic(int n) : lvl(n), ptr(n), q(n), g(n) {}
	void addEdge(int a, int b, ll c, ll rcap = 0) {
		g[a].push_back({b, sz(g[b]), c, c});
		g[b].push_back({a, sz(g[a]) - 1, rcap, rcap});
	}
	ll dfs(int v, int t, ll f) {
		if (v == t || !f) return f;
		for (int& i = ptr[v]; i < sz(g[v]); i++) {
			Edge& e = g[v][i];
			if (lvl[e.to] == lvl[v] + 1)
				if (ll p = dfs(e.to, t, min(f, e.c))) {
					e.c -= p, g[e.to][e.rev].c += p;
					return p;
				}
		}
		return 0;
	}
	ll calc(int s, int t) {
		ll flow = 0; q[0] = s;
		rep(L,0,31) do {
			lvl = ptr = vi(sz(q));
			int qi = 0, qe = lvl[s] = 1;
			while (qi < qe && !lvl[t]) {
				int v = q[qi++];
				for (Edge e : g[v])
					if (!lvl[e.to] && e.c >> (30 - L))
						q[qe++] = e.to, lvl[e.to] = lvl[v] + 1;
			}
			while (ll p = dfs(s, t, LLONG_MAX)) flow += p;
		} while (lvl[t]);
		return flow;
	}
	bool leftOfMinCut(int a) { return lvl[a] != 0; }
};

vec<pii> generalMatching(int N, vec<pii>& ed) {
	mt19937 mt(time(0));
	vec<vec<ll>> mat(N, vec<ll>(N)), A;
	for (auto [a, b] : ed) {
		int r = mt() % mod;
		mat[a][b] = r, mat[b][a] = (mod - r) % mod;
	}
	int r = matInv(A = mat), M = 2*N - r, fi, fj;
	assert(r % 2 == 0);
	if (M != N) do {
		mat.resize(M, vec<ll>(M));
		rep(i,0,N) {
			mat[i].resize(M);
			rep(j,N,M) {
				int r = mt() % mod;
				mat[i][j] = r, mat[j][i] = (mod - r) % mod;
			}
		}
	} while (matInv(A = mat) != M);
	vi has(M, 1); vec<pii> ret;
	rep(it,0,M/2) {
		rep(i,0,M) if (has[i])
			rep(j,i+1,M) if (A[i][j] && mat[i][j]) {
				fi = i; fj = j; goto done;
		} assert(0); done:
		if (fj < N) ret.push_back({fi, fj});
		has[fi] = has[fj] = 0;
		rep(sw,0,2) {
			ll a = modpow(A[fi][fj], mod-2);
			rep(i,0,M) if (has[i] && A[i][fj]) {
				ll b = A[i][fj] * a % mod;
				rep(j,0,M) A[i][j] = (A[i][j] - A[fi][j] * b) % mod;
			}
			swap(fi,fj);
		}
	}
	return ret;
}

int hopcroftKarp(vec<vi>& g, vi& r) {
	int n = sz(g), res = 0;
	vi l(n, -1), q(n), d(n);
	auto dfs = [&](auto f, int u) -> bool {
		int t = exchange(d[u], 0) + 1;
		for (int v : g[u])
			if (r[v] == -1 || (d[r[v]] == t && f(f, r[v])))
				return l[u] = v, r[v] = u, 1;
		return 0;
	};
	for (int t = 0, f = 0;; t = f = 0, d.assign(n, 0)) {
		rep(i,0,n) if (l[i] == -1) q[t++] = i, d[i] = 1;
		rep(i,0,t) for (int v : g[q[i]]) {
			if (r[v] == -1) f = 1;
			else if (!d[r[v]]) d[r[v]] = d[q[i]] + 1, q[t++] = r[v];
		}
		if (!f) return res;
		rep(i,0,n) if (l[i] == -1) res += dfs(dfs, i);
	}
}

template <class T> struct FlowDemands {
	int n;
	T mf;
	vec<ll> in, out;
	FlowDemands(int n): n(n), mf(n+2), in(n), out(n) {}
	void addEdge(int u, int v, ll cap, ll dem = 0) {
		mf.addEdge(u, v, cap - dem);
		out[u] += dem, in[v] += dem;
	}
	ll calc(int s, int t) {
		const ll inf = 1e9;
		mf.addEdge(t, s, inf);
		rep(i,0,n) {
			mf.addEdge(n, i, in[i]);
			mf.addEdge(i, n+1, out[i]);
		}
		return mf.calc(n, n+1);
	}
};

#include <bits/extc++.h>
const ll INF = numeric_limits<ll>::max() / 4;
struct MCMF {
	struct Edge {
		int from, to, rev;
		ll cap, cost, flow;
	};
	int N;
	vec<vec<Edge>> ed;
	vi seen;
	vec<ll> dist, pi;
	vec<Edge*> par;
	MCMF(int N) : N(N), ed(N), seen(N), dist(N), pi(N), par(N) {}
	void addEdge(int from, int to, ll cap, ll cost) {
		if (from == to) return;
		ed[from].push_back({from,to,sz(ed[to]),cap,cost,0});
		ed[to].push_back({to,from,sz(ed[from])-1,0,-cost,0});
	}
	void path(int s) {
		fill(all(seen), 0);
		fill(all(dist), INF);
		dist[s] = 0; ll di;
		__gnu_pbds::priority_queue<pair<ll, int>> q;
		vec<decltype(q)::point_iterator> its(N);
		q.push({ 0, s });
		while (!q.empty()) {
			s = q.top().second; q.pop();
			seen[s] = 1; di = dist[s] + pi[s];
			for (Edge& e : ed[s]) if (!seen[e.to]) {
				ll val = di - pi[e.to] + e.cost;
				if (e.cap - e.flow > 0 && val < dist[e.to]) {
					dist[e.to] = val;
					par[e.to] = &e;
					if (its[e.to] == q.end())
						its[e.to] = q.push({ -dist[e.to], e.to });
					else
						q.modify(its[e.to], { -dist[e.to], e.to });
				}
			}
		}
		rep(i,0,N) pi[i] = min(pi[i] + dist[i], INF);
	}
	pair<ll, ll> maxflow(int s, int t) {
		ll totflow = 0, totcost = 0;
		while (path(s), seen[t]) {
			ll fl = INF;
			for (Edge* x = par[t]; x; x = par[x->from])
				fl = min(fl, x->cap - x->flow);
			totflow += fl;
			for (Edge* x = par[t]; x; x = par[x->from]) {
				x->flow += fl;
				ed[x->to][x->rev].flow -= fl;
			}
		}
		rep(i,0,N) for (Edge& e : ed[i]) totcost += e.cost * e.flow;
		return {totflow, totcost/2};
	}
	void setpi(int s) {
		fill(all(pi), INF); pi[s] = 0;
		int it = N, ch = 1; ll v;
		while (ch-- && it--)
			rep(i,0,N) if (pi[i] != INF)
				for (Edge& e : ed[i]) if (e.cap)
					if ((v = pi[i] + e.cost) < pi[e.to])
						pi[e.to] = v, ch = 1;
		assert(it >= 0);
	}
};

struct PushRelabel {
	struct Edge {
		int to, rev;
		ll f, c;
		ll flow() { return max(f, ll(0)); }
	};
	vec<vec<Edge>> g;
	vec<ll> ec;
	vec<Edge*> cur;
	vec<vi> hs; vi H;
	PushRelabel(int n) : g(n), ec(n), cur(n), hs(2*n), H(n) {}
	void addEdge(int s, int t, ll cap, ll rcap=0) {
		if (s == t) return;
		g[s].push_back({t, sz(g[t]), 0, cap});
		g[t].push_back({s, sz(g[s])-1, 0, rcap});
	}
	void addFlow(Edge& e, ll f) {
		Edge &back = g[e.to][e.rev];
		if (!ec[e.to] && f) hs[H[e.to]].push_back(e.to);
		e.f += f; e.c -= f; ec[e.to] += f;
		back.f -= f; back.c += f; ec[back.to] -= f;
	}
	ll calc(int s, int t) {
		int v = sz(g); H[s] = v; ec[t] = 1;
		vi co(2*v); co[0] = v-1;
		rep(i,0,v) cur[i] = g[i].data();
		for (Edge& e : g[s]) addFlow(e, e.c);
		for (int hi = 0;;) {
			while (hs[hi].empty()) if (!hi--) return -ec[s];
			int u = hs[hi].back(); hs[hi].pop_back();
			while (ec[u] > 0)
				if (cur[u] == g[u].data() + sz(g[u])) {
					H[u] = 1e9;
					for (Edge& e : g[u]) if (e.c && H[u] > H[e.to]+1)
						H[u] = H[e.to]+1, cur[u] = &e;
					if (++co[H[u]], !--co[hi] && hi < v)
						rep(i,0,v) if (hi < H[i] && H[i] < v)
							--co[H[i]], H[i] = v + 1;
					hi = H[u];
				} else if (cur[u]->c && H[u] == H[cur[u]->to]+1)
					addFlow(*cur[u], min(ec[u], cur[u]->c));
				else ++cur[u];
		}
	}
	bool leftOfMinCut(int a) { return H[a] >= sz(g); }
};

template <class T>
pair<T, vi> weightedMatching(vec<vec<T>>& C) {
	int i = sz(C), m = i ? sz(C[0]) : 0, c, s, r;
	vec<T> dist(m), pot(m);
	vi match(i), rev(m, -1), cols(m), prev(m);
	T d = 0, nd, cost = 0;
	while (i--) {
		rep(c,0,m) dist[c] = C[i][c], cols[c] = c, prev[c] = i;
		for (s = 0;;) {
			rep(j,s,m) {
				c = cols[j], nd = dist[c] - pot[c];
				if (j == s || d > nd) d = nd, swap(cols[s], cols[j]);
			}
			if ((r = rev[c = cols[s++]]) == -1) break;
			rep(j,0,m) if (dist[j] > (nd = C[r][j]-C[r][c]+dist[c]))
				dist[j] = nd, prev[j] = r;
		}
		cost += dist[c];
		while (s--) pot[cols[s]] = dist[cols[s]] - d;
		for (; r != i; swap(c, match[r]))
			r = rev[c] = prev[c];
	}
	return {cost, match};
}

typedef Point<double> P;
#define arg(p, q) atan2(p.cross(q), p.dot(q))
double circlePoly(P c, double r, vec<P> ps) {
	auto tri = [&](P p, P q) {
		auto r2 = r * r / 2;
		P d = q - p;
		auto a = d.dot(p)/d.dist2(), b = (p.dist2()-r*r)/d.dist2();
		auto det = a * a - b;
		if (det <= 0) return arg(p, q) * r2;
		auto s = max(0., -a-sqrt(det)), t = min(1., -a+sqrt(det));
		if (t < 0 || 1 <= s) return arg(p, q) * r2;
		P u = p + d * s, v = q + d * (t-1);
		return arg(p,u) * r2 + u.cross(v)/2 + arg(v,q) * r2;
	};
	auto sum = 0.0;
	rep(i,0,sz(ps))
		sum += tri(ps[i] - c, ps[(i + 1) % sz(ps)] - c);
	return sum;
}

using P = Point<double>;
double ccRadius(const P& A, const P& B, const P& C) {
	return (B-A).dist()*(C-B).dist()*(A-C).dist()/
			abs((B-A).cross(C-A))/2;
}
P ccCenter(const P& A, const P& B, const P& C) {
	P b = C-A, c = B-A;
	return A + (b*c.dist2()-c*b.dist2()).perp()/b.cross(c)/2;
}

using P = Point<ll>;
array<P, 2> closest(vec<P> v) {
	assert(sz(v) > 1);
	set<P> S;
	sort(all(v), [](P a, P b) { return a.y < b.y; });
	pair<ll, array<P, 2>> ret{LLONG_MAX, {P(), P()}};
	int j = 0;
	for (P p : v) {
		P d{1 + (ll)sqrt(ret.first), 0};
		while (v[j].y <= p.y - d.x) S.erase(v[j++]);
		auto lo = S.lower_bound(p - d), hi = S.upper_bound(p + d);
		for (; lo != hi; ++lo)
			ret = min(ret, {(*lo - p).dist2(), {*lo, p}});
		S.insert(p);
	}
	return ret.second;
}

using P = Point<ll>;
vec<P> convexHull(vec<P> pts) {
	if (sz(pts) <= 1) return pts;
	sort(all(pts));
	vec<P> h(sz(pts)+1);
	int s = 0, t = 0;
	for (int it = 2; it--; s = --t, reverse(all(pts)))
		for (P p : pts) {
			while (t >= s + 2 && h[t-2].cross(h[t-1], p) <= 0) t--;
			h[t++] = p;
		}
	return {h.begin(), h.begin() + t - (t == 2 && h[0] == h[1])};
}

using P = Point<ll>;
typedef struct Quad* Q;
using lll = __int128_t;
P arb(LLONG_MAX,LLONG_MAX);
struct Quad {
	Q rot, o; P p = arb; bool mark;
	P& F() { return r()->p; }
	Q& r() { return rot->rot; }
	Q prev() { return rot->o->rot; }
	Q next() { return r()->prev(); }
} *H;
bool circ(P p, P a, P b, P c) {
	lll p2 = p.dist2(), A = a.dist2()-p2,
			B = b.dist2()-p2, C = c.dist2()-p2;
	return p.cross(a,b)*C + p.cross(b,c)*A + p.cross(c,a)*B > 0;
}
Q makeEdge(P orig, P dest) {
	Q r = H ? H : new Quad{new Quad{new Quad{new Quad{0}}}};
	H = r->o; r->r()->r() = r;
	rep(i,0,4) r = r->rot, r->p = arb, r->o = i & 1 ? r : r->r();
	r->p = orig; r->F() = dest;
	return r;
}
void splice(Q a, Q b) {
	swap(a->o->rot->o, b->o->rot->o); swap(a->o, b->o);
}
Q connect(Q a, Q b) {
	Q q = makeEdge(a->F(), b->p);
	splice(q, a->next());
	splice(q->r(), b);
	return q;
}
pair<Q,Q> rec(const vec<P>& s) {
	if (sz(s) <= 3) {
		Q a = makeEdge(s[0], s[1]), b = makeEdge(s[1], s.back());
		if (sz(s) == 2) return { a, a->r() };
		splice(a->r(), b);
		auto side = s[0].cross(s[1], s[2]);
		Q c = side ? connect(b, a) : 0;
		return {side < 0 ? c->r() : a, side < 0 ? c : b->r() };
	}
#define H(e) e->F(), e->p
#define valid(e) (e->F().cross(H(base)) > 0)
	int half = sz(s) / 2;
	auto [ra, A] = rec({all(s) - half});
	auto [B, rb] = rec({sz(s) - half + all(s)});
	while ((B->p.cross(H(A)) < 0 && (A = A->next())) ||
				 (A->p.cross(H(B)) > 0 && (B = B->r()->o)));
	Q base = connect(B->r(), A);
	if (A->p == ra->p) ra = base->r();
	if (B->p == rb->p) rb = base;
#define DEL(e, init, dir) Q e = init->dir; if (valid(e)) \
		while (circ(e->dir->F(), H(base), e->F())) { \
			Q t = e->dir; \
			splice(e, e->prev()); \
			splice(e->r(), e->r()->prev()); \
			e->o = H; H = e; e = t; \
		}
	for (;;) {
		DEL(LC, base->r(), o);  DEL(RC, base, prev());
		if (!valid(LC) && !valid(RC)) break;
		if (!valid(LC) || (valid(RC) && circ(H(RC), H(LC))))
			base = connect(RC, base->r());
		else
			base = connect(base->r(), LC->r());
	}
	return { ra, rb };
}
vec<P> triangulate(vec<P> pts) {
	sort(all(pts));  assert(unique(all(pts)) == pts.end());
	if (sz(pts) < 2) return {};
	Q e = rec(pts).first;
	vec<Q> q = {e};
	int qi = 0;
	while (e->o->F().cross(e->F(), e->p) < 0) e = e->o;
#define ADD { Q c = e; do { c->mark = 1; pts.push_back(c->p); \
	q.push_back(c->r()); c = c->next(); } while (c != e); }
	ADD; pts.clear();
	while (qi < sz(q)) if (!(e = q[qi++])->mark) ADD;
	return pts;
}

using P = Point<double>;
struct Line {
	P p, q;
	double a;
	Line() {}
	Line(P p, P q) : p(p), q(q), a((q - p).angle()) {}
	bool operator<(Line o) const { return a < o.a; }
};
vec<P> halfPlaneIntersection(vec<Line> v) {
	sort(all(v));
	ll n = sz(v), q = 1, h = 0;
	const double eps = 1e-9;
	vec<Line> c(n+2);
#define L(a) a.p, a.q
#define PQ(a) (a.q - a.p)
#define I(j, k) lineInter(L(c[j]), L(c[k])).snd
	rep(i,0,n) {
		while (q < h && sideOf(L(v[i]), I(h, h-1), eps) < 0) h--;
		while (q < h && sideOf(L(v[i]), I(q, q+1), eps) < 0) q++;
		c[++h] = v[i];
		if (q < h && abs(PQ(c[h]).cross(PQ(c[h-1]))) < eps) {
			if (PQ(c[h]).dot(PQ(c[h-1])) <= 0) return {};
			if (sideOf(L(v[i]), c[--h].p, eps) < 0) c[h] = v[i];
		}
	}
	while (q < h - 1 && sideOf(L(c[q]), I(h, h-1), eps) < 0) h--;
	while (q < h - 1 && sideOf(L(c[h]), I(q, q+1), eps) < 0) q++;
	if (h - q <= 1) return {};
	c[++h] = c[q];
	vec<P> s;
	rep(i,q,h) s.pb(I(i, i+1));
	return s;
#undef L
#undef PQ
#undef I
}

typedef Point3D<double> P3;
struct PR {
	void ins(int x) { (a == -1 ? a : b) = x; }
	void rem(int x) { (a == x ? a : b) = -1; }
	int cnt() { return (a != -1) + (b != -1); }
	int a, b;
};
struct F { P3 q; int a, b, c; };
vec<F> hull3d(const vec<P3>& A) {
	assert(sz(A) >= 4);
	vec<vec<PR>> E(sz(A), vec<PR>(sz(A), {-1, -1}));
#define E(x,y) E[f.x][f.y]
	vec<F> FS;
	auto mf = [&](int i, int j, int k, int l) {
		P3 q = (A[j] - A[i]).cross((A[k] - A[i]));
		if (q.dot(A[l]) > q.dot(A[i]))
			q = q * -1;
		F f{q, i, j, k};
		E(a,b).ins(k); E(a,c).ins(j); E(b,c).ins(i);
		FS.push_back(f);
	};
	rep(i,0,4) rep(j,i+1,4) rep(k,j+1,4)
		mf(i, j, k, 6 - i - j - k);
	rep(i,4,sz(A)) {
		rep(j,0,sz(FS)) {
			F f = FS[j];
			if (f.q.dot(A[i]) > f.q.dot(A[f.a])) {
				E(a,b).rem(f.c);
				E(a,c).rem(f.b);
				E(b,c).rem(f.a);
				swap(FS[j--], FS.back());
				FS.pop_back();
			}
		}
		int nw = sz(FS);
		rep(j,0,nw) {
			F f = FS[j];
#define C(a, b, c) if (E(a,b).cnt() != 2) mf(f.a, f.b, i, f.c);
			C(a, b, c); C(a, c, b); C(b, c, a);
		}
	}
	for (F& it : FS) if ((A[it.b] - A[it.a]).cross(
		A[it.c] - A[it.a]).dot(it.q) <= 0) swap(it.c, it.b);
	return FS;
};

template <class P>
bool inPolygon(vec<P> &p, P a, bool strict = true) {
	int cnt = 0, n = sz(p);
	rep(i,0,n) {
		P q = p[(i + 1) % n];
		if (onSegment(p[i], q, a)) return !strict;
		cnt ^= ((a.y<p[i].y) - (a.y<q.y)) * a.cross(p[i], q) > 0;
	}
	return cnt;
}

template <class P>
double lineDist(const P& a, const P& b, const P& p) {
	return (double)(b-a).cross(p-a)/(b-a).dist();
}

#define cmp(i,j) sgn(dir.perp().cross(poly[(i)%n]-poly[(j)%n]))
#define extr(i) cmp(i + 1, i) >= 0 && cmp(i, i - 1 + n) < 0
template <class P> int extrVertex(vec<P>& poly, P dir) {
	int n = sz(poly), lo = 0, hi = n;
	if (extr(0)) return 0;
	while (lo + 1 < hi) {
		int m = (lo + hi) / 2;
		if (extr(m)) return m;
		int ls = cmp(lo + 1, lo), ms = cmp(m + 1, m);
		(ls < ms || (ls == ms && ls == cmp(lo, m)) ? hi : lo) = m;
	}
	return lo;
}
template <class P>
pii lineHull(P a, P b, vec<P>& poly) {
	int endA = extrVertex(poly, (a - b).perp());
	int endB = extrVertex(poly, (b - a).perp());
	if (cmpL(endA) < 0 || cmpL(endB) > 0)
		return {-1, -1};
	pii res;
	rep(i,0,2) {
		int lo = endB, hi = endA, n = sz(poly);
		while ((lo + 1) % n != hi) {
			int m = ((lo + hi + (lo < hi ? 0 : n)) / 2) % n;
			(cmpL(m) == cmpL(endB) ? lo : hi) = m;
		}
		res[i] = (lo + !cmpL(hi)) % n;
		swap(endA, endB);
	}
	if (res[0] == res[1]) return {res[0], -1};
	if (!cmpL(res[0]) && !cmpL(res[1]))
		switch ((res[0] - res[1] + sz(poly) + 1) % sz(poly)) {
			case 0: return {res[0], res[0]};
			case 2: return {res[1], res[1]};
		}
	return res;
}

template <class P>
pair<int, P> lineInter(P a, P b, P c, P d) {
	auto m = (b - a).cross(d - c);
	if (m == 0)
		return {-(a.cross(b, c) == 0), P(0, 0)};
	auto p = c.cross(b, d), q = c.cross(d, a);
	return {1, (a * p + b * q) / m};
}

using P = Point<double>;
P linearTransformation(const P& a, const P& b,
		const P& c, const P& d, const P& r) {
	P dp = b-a, dq = d-c, num(dp.cross(dq), dp.dot(dq));
	return c + P((r-a).cross(num), (r-a).dot(num))/dp.dist2();
}

using P = Point<int>;
vec<array<int, 3>> manhattanMST(vec<P> ps) {
	vi id(sz(ps));
	iota(all(id), 0);
	vec<array<int, 3>> edges;
	rep(k,0,4) {
		sort(all(id), [&](int i, int j) {
				 return (ps[i]-ps[j]).x < (ps[j]-ps[i]).y;});
		map<int, int> sweep;
		for (int i : id) {
			for (auto it = sweep.lower_bound(-ps[i].y);
								it != sweep.end(); sweep.erase(it++)) {
				int j = it->second;
				P d = ps[i] - ps[j];
				if (d.y > d.x) break;
				edges.push_back({d.y + d.x, i, j});
			}
			sweep[-ps[i].y] = i;
		}
		for (P& p : ps) if (k & 1) p.x = -p.x; else swap(p.x, p.y);
	}
	return edges;
}

auto mec(vec<P> ps) {
	shuffle(all(ps), mt19937(time(0)));
	P o = ps[0];
	double r = 0, EPS = 1 + 1e-8;
	rep(i,0,sz(ps)) if ((o - ps[i]).dist() > r * EPS) {
		o = ps[i], r = 0;
		rep(j,0,i) if ((o - ps[j]).dist() > r * EPS) {
			o = (ps[i] + ps[j]) / 2;
			r = (o - ps[i]).dist();
			rep(k,0,j) if ((o - ps[k]).dist() > r * EPS) {
				o = ccCenter(ps[i], ps[j], ps[k]);
				r = (o - ps[i]).dist();
			}
		}
	}
	return pair{o, r};
}

void reorder(vec<P> &p) {
	if (sideOf(p[0], p[1], p[2]) < 0) reverse(all(p));
	rotate(p.begin(), min_element(all(p)), p.end());
}
vec<P> minkowskiSum(vec<P> p, vec<P> q) {
	if (min(sz(p), sz(q)) < 3) {
		vec<P> v;
		for (P pp : p) for (P qq : q) v.pb(pp + qq);
		return convexHull(v);
	}
	reorder(p), reorder(q);
	rep(i,0,2) p.pb(p[i]), q.pb(q[i]);
	vec<P> r;
	ll i = 0, j = 0;
	while (i + 2 < sz(p) || j + 2 < sz(q)) {
		r.pb(p[i] + q[j]);
		ll cross = (p[i + 1] - p[i]).cross(q[j + 1] - q[j]);
		i += cross >= 0, j += cross <= 0;
	}
	return r;
}

template <class P> bool onSegment(P s, P e, P p) {
	return p.cross(s, e) == 0 && (s - p).dot(e - p) <= 0;
}

template <class T> int sgn(T x) { return (x > 0) - (x < 0); }
template <class T>
struct Point {
	typedef Point P;
	T x, y;
	explicit Point(T x=0, T y=0) : x(x), y(y) {}
	bool operator<(P p) const { return tie(x,y) < tie(p.x,p.y); }
	bool operator==(P p) const { return tie(x,y)==tie(p.x,p.y); }
	P operator+(P p) const { return P(x+p.x, y+p.y); }
	P operator-(P p) const { return P(x-p.x, y-p.y); }
	P operator*(T d) const { return P(x*d, y*d); }
	P operator/(T d) const { return P(x/d, y/d); }
	T dot(P p) const { return x*p.x + y*p.y; }
	T cross(P p) const { return x*p.y - y*p.x; }
	T cross(P a, P b) const { return (a-*this).cross(b-*this); }
	T dist2() const { return x*x + y*y; }
	double dist() const { return sqrt((double)dist2()); }
	double angle() const { return atan2(y, x); }
	P unit() const { return *this/dist(); }
	P perp() const { return P(-y, x); }
	P normal() const { return perp().unit(); }
	P rotate(double a) const {
		return P(x*cos(a)-y*sin(a),x*sin(a)+y*cos(a)); }
	friend ostream& operator<<(ostream& os, P p) {
		return os << "(" << p.x << "," << p.y << ")"; }
};

template <class T>
struct Point3D {
	typedef Point3D P;
	typedef const P& R;
	T x, y, z;
	explicit Point3D(T x=0, T y=0, T z=0) : x(x), y(y), z(z) {}
	bool operator<(R p) const {
		return tie(x, y, z) < tie(p.x, p.y, p.z); }
	bool operator==(R p) const {
		return tie(x, y, z) == tie(p.x, p.y, p.z); }
	P operator+(R p) const { return P(x+p.x, y+p.y, z+p.z); }
	P operator-(R p) const { return P(x-p.x, y-p.y, z-p.z); }
	P operator*(T d) const { return P(x*d, y*d, z*d); }
	P operator/(T d) const { return P(x/d, y/d, z/d); }
	T dot(R p) const { return x*p.x + y*p.y + z*p.z; }
	P cross(R p) const {
		return P(y*p.z - z*p.y, z*p.x - x*p.z, x*p.y - y*p.x);
	}
	T dist2() const { return x*x + y*y + z*z; }
	double dist() const { return sqrt((double)dist2()); }
	double phi() const { return atan2(y, x); }
	double theta() const { return atan2(sqrt(x*x+y*y),z); }
	P unit() const { return *this/(T)dist(); }
	P normal(P p) const { return cross(p).unit(); }
	P rotate(double angle, P axis) const {
		double s = sin(angle), c = cos(angle); P u = axis.unit();
		return u*dot(u)*(1-c) + (*this)*c - cross(u)*s;
	}
};

template <class T>
T polygonArea2(vec<Point<T>>& v) {
	T a = v.back().cross(v[0]);
	rep(i,0,sz(v)-1) a += v[i].cross(v[i+1]);
	return a;
}

typedef Point<double> P;
P polygonCenter(const vec<P>& v) {
	P res(0, 0); double A = 0;
	for (int i = 0, j = sz(v) - 1; i < sz(v); j = i++) {
		res = res + (v[i] + v[j]) * v[j].cross(v[i]);
		A += v[j].cross(v[i]);
	}
	return res / A / 3;
}

typedef Point<double> P;
vec<P> polygonCut(const vec<P>& poly, P s, P e) {
	vec<P> res;
	rep(i,0,sz(poly)) {
		P cur = poly[i], prev = i ? poly[i-1] : poly.back();
		auto a = s.cross(e, cur), b = s.cross(e, prev);
		if ((a < 0) != (b < 0))
			res.push_back(cur + (prev - cur) * (a / (a - b)));
		if (a < 0)
			res.push_back(cur);
	}
	return res;
}

typedef Point<double> P;
double rat(P a, P b) { return sgn(b.x) ? a.x/b.x : a.y/b.y; }
double polyUnion(vec<vec<P>>& poly) {
	double ret = 0;
	rep(i,0,sz(poly)) rep(v,0,sz(poly[i])) {
		P A = poly[i][v], B = poly[i][(v + 1) % sz(poly[i])];
		vec<pair<double, int>> segs = {{0, 0}, {1, 0}};
		rep(j,0,sz(poly)) if (i != j) {
			rep(u,0,sz(poly[j])) {
				P C = poly[j][u], D = poly[j][(u + 1) % sz(poly[j])];
				int sc = sideOf(A, B, C), sd = sideOf(A, B, D);
				if (sc != sd) {
					double sa = C.cross(D, A), sb = C.cross(D, B);
					if (min(sc, sd) < 0)
						segs.emplace_back(sa / (sa - sb), sgn(sc - sd));
				} else if (!sc && !sd && j<i && sgn((B-A).dot(D-C))>0){
					segs.emplace_back(rat(C - A, B - A), 1);
					segs.emplace_back(rat(D - A, B - A), -1);
				}
			}
		}
		sort(all(segs));
		for (auto& s : segs) s.first = min(max(s.first, 0.0), 1.0);
		double sum = 0;
		int cnt = segs[0].second;
		rep(j,1,sz(segs)) {
			if (!cnt) sum += segs[j].first - segs[j - 1].first;
			cnt += segs[j].second;
		}
		ret += A.cross(B) * sum;
	}
	return ret / 2;
}

template <class V, class L>
double signedPolyVolume(const V& p, const L& trilist) {
	double v = 0;
	for (auto i : trilist) v += p[i.a].cross(p[i.b]).dot(p[i.c]);
	return v / 6;
}

using P = Point<double>;
double segDist(P& s, P& e, P& p) {
	if (s==e) return (p-s).dist();
	auto d = (e-s).dist2(), t = min(d,max(.0,(p-s).dot(e-s)));
	return ((p-s)*d-(e-s)*t).dist()/d;
}

template <class P> vec<P> segInter(P a, P b, P c, P d) {
	auto oa = c.cross(d, a), ob = c.cross(d, b),
			 oc = a.cross(b, c), od = a.cross(b, d);
	if (sgn(oa) * sgn(ob) < 0 && sgn(oc) * sgn(od) < 0)
		return {(a * ob - b * oa) / (ob - oa)};
	set<P> s;
	if (onSegment(c, d, a)) s.insert(a);
	if (onSegment(c, d, b)) s.insert(b);
	if (onSegment(a, b, c)) s.insert(c);
	if (onSegment(a, b, d)) s.insert(d);
	return {all(s)};
}

template <class P>
ll sideOf(P s, P e, P p) { return sgn(s.cross(e, p)); }
template <class P>
ll sideOf(const P& s, const P& e, const P& p, double eps) {
	auto a = (e-s).cross(p-s);
	double l = (e-s).dist()*eps;
	return (a > l) - (a < -l);
}

double sphericalDistance(double f1, double t1,
		double f2, double t2, double radius) {
	double dx = sin(t2)*cos(f2) - sin(t1)*cos(f1);
	double dy = sin(t2)*sin(f2) - sin(t1)*sin(f1);
	double dz = cos(t2) - cos(t1);
	double d = sqrt(dx*dx + dy*dy + dz*dz);
	return radius*2*asin(d/2);
}

struct TwoSat {
	int N;
	vec<vi> gr;
	vi values;
	TwoSat(int n = 0) : N(n), gr(2*n) {}
	void either(int f, int j) {
		f = max(2*f, -1-2*f), j = max(2*j, -1-2*j);
		gr[f].pb(j^1), gr[j].pb(f^1);
	}
	void setValue(int x) { either(x, x); }
	vi val, comp, z; int time = 0;
	int dfs(int i) {
		int low = val[i] = ++time, x; z.pb(i);
		for (int e : gr[i]) if (!comp[e])
			low = min(low, val[e] ?: dfs(e));
		if (low == val[i]) do {
			x = z.back(); z.pop_back();
			comp[x] = low;
			if (values[x>>1] == -1)
				values[x>>1] = x&1;
		} while (x != i);
		return val[i] = low;
	}
	bool solve() {
		values.assign(N, -1);
		val.assign(2*N, 0); comp = val;
		rep(i,0,2*N) if (!comp[i]) dfs(i);
		rep(i,0,N) if (comp[2*i] == comp[2*i+1]) return 0;
		return 1;
	}
	int addVar() {
		gr.emplace_back();
		gr.emplace_back();
		return N++;
	}
	void atMostOne(const vi& li) {
		if (sz(li) <= 1) return;
		int cur = ~li[0];
		rep(i,2,sz(li)) {
			int next = addVar();
			either(cur, ~li[i]);
			either(cur, next);
			either(~li[i], next);
			cur = ~next;
		}
		either(cur, ~li[1]);
	}
};

const ll inf = LLONG_MAX;
struct Ed { int a, b, w, s() { return a < b ? a : -a; }};
struct Node { ll dist = inf; int prev = -1; };
void bellmanFord(vec<Node>& nodes, vec<Ed>& eds, int s) {
	nodes[s].dist = 0;
	sort(all(eds), [](Ed a, Ed b) { return a.s() < b.s(); });
	int lim = sz(nodes) / 2 + 2;
	rep(i,0,lim) for (Ed ed : eds) {
		Node cur = nodes[ed.a], &dest = nodes[ed.b];
		if (abs(cur.dist) == inf) continue;
		ll d = cur.dist + ed.w;
		if (d < dest.dist) {
			dest.prev = ed.a;
			dest.dist = (i < lim-1 ? d : -inf);
		}
	}
	rep(i,0,lim) for (Ed e : eds) {
		if (nodes[e.a].dist == -inf)
			nodes[e.b].dist = -inf;
	}
}

struct Lift {
	vi d, p, j;
	Lift(vec<vi>& C) : d(sz(C)), p(d), j(d) { dfs(C, 0); }
	void dfs(vec<vi>& C, int u) {
		int jmp = (d[u] + d[j[j[u]]] == 2 * d[j[u]]) ? j[j[u]] : u;
		for (int v : C[u]) if (v != p[u])
			d[v] = d[p[v] = u] + 1, j[v] = jmp, dfs(C, v);
	}
	int lca(int u, int v) {
		if (d[u] < d[v]) swap(u, v);
		while (d[u] > d[v]) u = d[j[u]] >= d[v] ? j[u] : p[u];
		if (u == v) return u;
		while (p[u] != p[v]) {
			if (j[u] != j[v]) u = j[u], v = j[v];
			else u = p[u], v = p[v];
		}
		return p[u];
	}
	int kth(int u, int k) {
		if (k > d[u]) return -1;
		k = d[u] - k;
		while (d[u] > k) u = d[j[u]] >= k ? j[u] : p[u];
		return u;
	}
};

auto bridges(const auto& g, int m) {
	int n = sz(g), num_ccs = 0, q = 0, s = 0;
	vi br_id(n, -1), is_br(m), tin(n), st(n);
	auto dfs = [&](auto&& self, int v, int p) -> int {
		int low = tin[v] = ++q;
		st[s++] = v;
		for (auto [u, e] : g[v])
			if (e != p && br_id[u] < 0)
				low = min(low, tin[u] ?: self(self, u, e));
		if (tin[v] == low) {
			if (p != -1) is_br[p] = 1;
			while (br_id[v] < 0) br_id[st[--s]] = num_ccs;
			num_ccs++;
		}
		return low;
	};
	rep(i,0,n)
		if (!tin[i]) dfs(dfs, i, -1);
	return tuple{num_ccs, br_id, is_br};
}

vi centroidTree(vec<vi>& g) {
	int n = sz(g);
	vi vis(n), P(n), S(n);
	auto calc_sz = [&](auto&& self, int v, int p) -> int {
		S[v] = 1;
		for (int y : g[v]) if (y != p && !vis[y])
			S[v] += self(self, y, v);
		return S[v];
	};
	auto dfs = [&](auto&& self, int v, int p, int s) -> void {
		if (s < 0) s = calc_sz(calc_sz, v, -1);
		for (int y : g[v]) if (!vis[y] && S[y] * 2 >= s) {
			S[v] = 0;
			self(self, y, p, s);
			return;
		}
		vis[v] = 1;
		P[v] = p;
		for (int y : g[v]) if (!vis[y]) self(self, y, v, -1);
	};
	dfs(dfs, 0, -1, -1);
	return P;
}

auto cuts(const auto& adj, int m) {
	int n = sz(adj), num_bccs = 0, q = 0, s = 0;
	vi bcc_id(m, -1), is_cut(n), tin(n), st(m);
	auto dfs = [&](auto&& self, int v, int p) -> int {
		int low = tin[v] = ++q;
		for (auto [u, e] : adj[v]) {
			assert(v != u);
			if (e == p) continue;
			if (tin[u] < tin[v]) st[s++] = e;
			int lu = -1;
			low = min(low, tin[u] ?: (lu = self(self, u, e)));
			if (lu >= tin[v]) {
				is_cut[v] = p >= 0 || tin[v] + 1 < tin[u];
				while (bcc_id[e] < 0) bcc_id[st[--s]] = num_bccs;
				num_bccs++;
			}
		}
		return low;
	};
	rep(i,0,n)
		if (!tin[i]) dfs(dfs, i, -1);
	return tuple{num_bccs, bcc_id, is_cut};
}

struct Edge { int a, b; ll w; };
struct Node {
	Edge key;
	Node *l, *r;
	ll delta;
	void prop() {
		key.w += delta;
		if (l) l->delta += delta;
		if (r) r->delta += delta;
		delta = 0;
	}
	Edge top() { prop(); return key; }
};
Node *merge(Node *a, Node *b) {
	if (!a || !b) return a ?: b;
	a->prop(), b->prop();
	if (a->key.w > b->key.w) swap(a, b);
	swap(a->l, (a->r = merge(b, a->r)));
	return a;
}
void pop(Node*& a) { a->prop(); a = merge(a->l, a->r); }
pair<ll, vi> dmst(int n, int r, vec<Edge>& g) {
	RollbackUF uf(n);
	vec<Node*> heap(n);
	for (Edge e : g) heap[e.b] = merge(heap[e.b], new Node{e});
	ll res = 0;
	vi seen(n, -1), path(n), par(n);
	seen[r] = r;
	vec<Edge> Q(n), in(n, {-1,-1}), comp;
	deque<tuple<int, int, vec<Edge>>> cycs;
	rep(s,0,n) {
		int u = s, qi = 0, w;
		while (seen[u] < 0) {
			if (!heap[u]) return {-1,{}};
			Edge e = heap[u]->top();
			heap[u]->delta -= e.w, pop(heap[u]);
			Q[qi] = e, path[qi++] = u, seen[u] = s;
			res += e.w, u = uf.find(e.a);
			if (seen[u] == s) {
				Node* cyc = 0;
				int end = qi, time = uf.time();
				do cyc = merge(cyc, heap[w = path[--qi]]);
				while (uf.join(u, w));
				u = uf.find(u), heap[u] = cyc, seen[u] = -1;
				cycs.push_front({u, time, {&Q[qi], &Q[end]}});
			}
		}
		rep(i,0,qi) in[uf.find(Q[i].b)] = Q[i];
	}
	for (auto& [u,t,comp] : cycs) {
		uf.rollback(t);
		Edge inEdge = in[u];
		for (auto& e : comp) in[uf.find(e.b)] = e;
		in[uf.find(inEdge.b)] = inEdge;
	}
	rep(i,0,n) par[i] = in[i].a;
	return {res, par};
}

vec<vi> dominator_tree(const vec<vi>& adj, int root) {
	int n = sz(adj) + 1, co = 0;
	vec<vi> ans(n), radj(n), child(n), sdomChild(n);
	vi label(n), rlabel(n), sdom(n), dom(n), par(n), bes(n);
	auto get = [&](auto self, int x) -> int {
		if (par[x] != x) {
			int t = self(self, par[x]);
			par[x] = par[par[x]];
			if (sdom[t] < sdom[bes[x]]) bes[x] = t;
		}
		return bes[x];
	};
	auto dfs = [&](auto self, int x) -> void {
		label[x] = ++co, rlabel[co] = x;
		sdom[co] = par[co] = bes[co] = co;
		for (auto y : adj[x]) {
			if (!label[y])
				self(self, y), child[label[x]].push_back(label[y]);
			radj[label[y]].push_back(label[x]);
		}
	};
	dfs(dfs, root);
	for (int i = co; i >= 1; --i) {
		for (auto j : radj[i])
			sdom[i] = min(sdom[i], sdom[get(get, j)]);
		if (i > 1) sdomChild[sdom[i]].push_back(i);
		for (auto j : sdomChild[i]) {
			int k = get(get, j);
			if (sdom[j] == sdom[k]) dom[j] = sdom[j];
			else dom[j] = k; }
		for (auto j : child[i]) par[j] = i;
	}
	for (int i = 2; i < co + 1; ++i) {
		if (dom[i] != sdom[i]) dom[i] = dom[dom[i]];
		ans[rlabel[dom[i]]].push_back(rlabel[i]);
	}
	return ans;
}

vi edgeColoring(int N, vec<pii> eds) {
	vi cc(N + 1), ret(sz(eds)), fan(N), free(N), loc;
	for (pii e : eds) ++cc[e[0]], ++cc[e[1]];
	int ncols = *max_element(all(cc)) + 1;
	vec<vi> adj(N, vi(ncols, -1));
	for (auto [u, v] : eds) {
		fan[0] = v;
		loc.assign(ncols, 0);
		int at = u, end = u, d, c = free[u], ind = 0, i = 0;
		while (d = free[v], !loc[d] && (v = adj[u][d]) != -1)
			loc[d] = ++ind, cc[ind] = d, fan[ind] = v;
		cc[loc[d]] = c;
		for (int cd = d; at != -1; cd ^= c ^ d, at = adj[at][cd])
			swap(adj[at][cd], adj[end = at][cd ^ c ^ d]);
		while (adj[fan[i]][d] != -1) {
			int left = fan[i], right = fan[++i], e = cc[i];
			adj[u][e] = left;
			adj[left][e] = u;
			adj[right][e] = -1;
			free[right] = e;
		}
		adj[u][d] = fan[i];
		adj[fan[i]][d] = u;
		for (int y : {fan[0], u, end})
			for (int& z = free[y] = 0; adj[y][z] != -1; z++);
	}
	rep(i,0,sz(eds))
		for (auto [u, v] = eds[i]; adj[u][ret[i]] != v;) ++ret[i];
	return ret;
}

vi eulerWalk(vec<vec<pii>>& gr, int nedges, int src=0) {
	int n = sz(gr);
	vi D(n), its(n), eu(nedges), ret, s = {src};
	D[src]++;
	while (!s.empty()) {
		int x = s.back(), &it = its[x], end = sz(gr[x]);
		if (it == end){ ret.push_back(x); s.pop_back(); continue; }
		auto [y, e] = gr[x][it++];
		if (!eu[e]) {
			D[x]--, D[y]++;
			eu[e] = 1; s.push_back(y);
		}}
	for (int x : D) if (x < 0 || sz(ret) != nedges+1) return {};
	return {ret.rbegin(), ret.rend()};
}

template <bool VALS_EDGES, class T> struct HLD {
	int N, time = 0;
	vec<vi> adj;
	vi par, siz, rt, pos;
	T st;
	HLD(vec<vi> adj, auto... args) : N(sz(adj)), adj(adj),
		par(N, -1), siz(N, 1), rt(N), pos(N), st(N, args...) {
				dfsSz(0); dfsHld(0);
	}
	void dfsSz(int v) {
		for (int& u : adj[v]) {
			adj[u].erase(find(all(adj[u]), v));
			par[u] = v;
			dfsSz(u);
			siz[v] += siz[u];
			if (siz[u] > siz[adj[v][0]]) swap(u, adj[v][0]);
		}
	}
	void dfsHld(int v) {
		pos[v] = time++;
		for (int u : adj[v]) {
			rt[u] = (u == adj[v][0] ? rt[v] : u);
			dfsHld(u);
		}
	}
	template <class B> void process(int u, int v, B op) {
		for (;; v = par[rt[v]]) {
			if (pos[u] > pos[v]) swap(u, v);
			if (rt[u] == rt[v]) break;
			op(pos[rt[v]], pos[v] + 1);
		}
		op(pos[u] + VALS_EDGES, pos[v] + 1);
	}
	void modifyPath(int u, int v, auto val) {
		process(u, v, [&](int l, int r) { st.upd(l, r, val); });
	}
	auto queryPath(int u, int v) {
		ll res = 0;
		process(u, v, [&](int l, int r) {
				res += st.query(l, r);
		});
		return res;
	}
	auto querySubtree(int v) {
		return st.query(pos[v] + VALS_EDGES, pos[v] + siz[v]);
	}
};

struct LCA {
	int T = 0;
	vi time, path, ret;
	SparseTable<int> rmq;
	LCA(vec<vi>& C) : time(sz(C)), rmq((dfs(C,0,-1), ret)) {}
	void dfs(vec<vi>& C, int v, int par) {
		time[v] = T++;
		for (int y : C[v]) if (y != par) {
			path.push_back(v), ret.push_back(time[v]);
			dfs(C, y, v);
		}
	}
	int lca(int a, int b) {
		if (a == b) return a;
		tie(a, b) = minmax(time[a], time[b]);
		return path[rmq.query(a, b)];
	}
};

struct LinkCut : SplayTree {
	LinkCut(int n) : SplayTree(n) {}
	int access(int x) {
		int u = x, v = 0;
		for (; u; v = u, u = T[u].p) {
			splay(u);
			int& ov = T[u].ch[1];
			T[u].vir += T[ov].sub;
			T[u].vir -= T[v].sub;
			ov = v; pull(u);
		}
		return splay(x), v;
	}
	void reroot(int x) {
		access(x); T[x].flip ^= 1; push(x);
	}
	void link(int u, int v) {
		reroot(u); access(v);
		T[v].vir += T[u].sub;
		T[u].p = v; pull(v);
	}
	void cut(int u, int v) {
		reroot(u); access(v);
		T[v].ch[0] = T[u].p = 0; pull(v);
	}
	int lca(int u, int v) {
		if (u == v) return u;
		access(u); int ret = access(v);
		return T[u].p ? ret : 0;
	}
	ll subtree(int u, int v) {
		reroot(v); access(u); return T[u].vir + T[u].self;
	}
	ll path(int u, int v) {
		reroot(u); access(v); return T[v].path;
	}
	void update(int u, ll v) {
		access(u); T[u].self = v; pull(u);
	}
};

vi matroidInter(int n, auto M1, auto M2) {
	vec<bool> b(n);
	vi I[2];
	bool converged = false;
	while (!converged) {
		I[0].clear(), I[1].clear();
		rep(u,0,n) I[b[u]].pb(u);
		M1.build(I[1]), M2.build(I[1]);
		vec<bool> target(n), pushed(n);
		queue<int> q;
		for (int u : I[0]) {
			target[u] = M2.oracle(u);
			if (M1.oracle(u)) pushed[u] = true, q.push(u);
		}
		vi p(n, -1); converged = true;
		while (sz(q)) {
			int u = q.front(); q.pop();
			if (target[u]) {
				converged = false;
				for (int v = u; v != -1; v = p[v]) b[v] = !b[v];
				break;
			}
			for (int v : I[!b[u]]) if (!pushed[v]) {
				if ((b[u] && M1.oracle(u, v)) ||
						(b[v] && M2.oracle(v, u)))
					p[v] = u, pushed[v] = true, q.push(v);
			}
		}
	}
	return I[1];
}

using vb = vec<bitset<200>>;
struct MaxClique {
	double limit=0.025, pk=0;
	struct Vertex { int i, d=0; };
	typedef vec<Vertex> vv;
	vb e;
	vv V;
	vec<vi> C;
	vi qmax, q, S, old;
	void init(vv& r) {
		for (auto& v : r) v.d = 0;
		for (auto& v : r) for (auto j : r) v.d += e[v.i][j.i];
		sort(all(r), [](auto a, auto b) { return a.d > b.d; });
		int mxD = r[0].d;
		rep(i,0,sz(r)) r[i].d = min(i, mxD) + 1;
	}
	void expand(vv& R, int lev = 1) {
		S[lev] += S[lev - 1] - old[lev];
		old[lev] = S[lev - 1];
		while (sz(R)) {
			if (sz(q) + R.back().d <= sz(qmax)) return;
			q.push_back(R.back().i);
			vv T;
			for(auto v:R) if (e[R.back().i][v.i]) T.push_back({v.i});
			if (sz(T)) {
				if (S[lev]++ / ++pk < limit) init(T);
				int j = 0, mxk = 1, mnk = max(sz(qmax) - sz(q) + 1, 1);
				C[1].clear(), C[2].clear();
				for (auto v : T) {
					int k = 1;
					auto f = [&](int i) { return e[v.i][i]; };
					while (any_of(all(C[k]), f)) k++;
					if (k > mxk) mxk = k, C[mxk + 1].clear();
					if (k < mnk) T[j++].i = v.i;
					C[k].push_back(v.i);
				}
				if (j > 0) T[j - 1].d = 0;
				rep(k,mnk,mxk + 1) for (int i : C[k])
					T[j].i = i, T[j++].d = k;
				expand(T, lev + 1);
			} else if (sz(q) > sz(qmax)) qmax = q;
			q.pop_back(), R.pop_back();
		}
	}
	vi maxClique() { init(V), expand(V); return qmax; }
	MaxClique(vb conn) : e(conn), C(sz(e)+1), S(sz(C)), old(S) {
		rep(i,0,sz(e)) V.push_back({i});
	}
};

auto scc(const auto& g) {
	int n = sz(g), num_sccs = 0, q = 0, s = 0;
	vi scc_id(n, -1), tin(n), st(n);
	auto dfs = [&](auto&& self, int v) -> int {
		int low = tin[v] = ++q;
		st[s++] = v;
		for (int u : g[v])
			if (scc_id[u] < 0)
				low = min(low, tin[u] ?: self(self, u));
		if (tin[v] == low) {
			while (scc_id[v] < 0) scc_id[st[--s]] = num_sccs;
			num_sccs++;
		}
		return low;
	};
	rep(i,0,n)
		if (!tin[i]) dfs(dfs, i);
	return pair{num_sccs, scc_id};
}

vi topoSort(const vec<vi>& gr) {
	vi indeg(sz(gr)), q;
	for (auto& li : gr) for (int x : li) indeg[x]++;
	rep(i,0,sz(gr)) if (indeg[i] == 0) q.push_back(i);
	rep(j,0,sz(q)) for (int x : gr[q[j]])
		if (--indeg[x] == 0) q.push_back(x);
	return q;
}

template <class T>
vi weightedMatroidInter(int n, vec<T> w, auto M1, auto M2) {
	using P = pair<T, int>;
	const P INF = {numeric_limits<T>::max(), INT_MAX};
	vec<bool> b(n), target(n), is_inside(n);
	vi I[2], from(n); vec<P> d(n);
	auto check_edge = [&](int u, int v) {
		return (b[u] && M1.oracle(u, v)) ||
					 (b[v] && M2.oracle(v, u));
	};
	while (true) {
		I[0].clear(), I[1].clear();
		rep(u,0,n) I[b[u]].pb(u);
		M1.build(I[1]), M2.build(I[1]);
		rep(u,0,n)
			target[u] = is_inside[u] = 0, from[u] = -1, d[u] = INF;
		deque<T> q;
		sort(all(I[0]), [&](int i, int j) { return w[i] < w[j]; });
		for (int u : I[0]) {
			target[u] = M2.oracle(u);
			if (M1.oracle(u)) {
				if (is_inside[u]) continue;
				d[u] = {w[u], 0};
				(sz(q) && d[u] > d[q.front()]) ?
					q.pb(u) : q.push_front(u);
				is_inside[u] = true;
			}
		}
		while (sz(q)) {
			int u = q.front(); q.pop_front();
			is_inside[u] = false;
			for (int v : I[!b[u]]) if (check_edge(u, v)) {
				P nd = {d[u].first + w[v], d[u].second + 1};
				if (nd < d[v]) {
					from[v] = u, d[v] = nd;
					if (is_inside[v]) continue;
					(sz(q) && d[v] > d[q.front()]) ?
						q.pb(v) : q.push_front(v);
					is_inside[v] = true;
				}
			}
		}
		P mini = INF; int targ = -1;
		for (int u : I[0])
			if (target[u] && d[u] < mini) mini = d[targ = u];
		if (targ != -1) for (int u = targ; u != -1; u = from[u])
			b[u] = !b[u], w[u] *= -1;
		else break;
	}
	return I[1];
}

using d = double;
pair<ll, ll> approximate(d x, ll N) {
	ll LP = 0, LQ = 1, P = 1, Q = 0, inf = LLONG_MAX; d y = x;
	for (;;) {
		ll lim = min(P ? (N-LP) / P : inf, Q ? (N-LQ) / Q : inf),
			 a = (ll)floor(y), b = min(a, lim),
			 NP = b*P + LP, NQ = b*Q + LQ;
		if (a > b) {
			return (abs(x - (d)NP / (d)NQ) < abs(x - (d)P / (d)Q)) ?
				make_pair(NP, NQ) : make_pair(P, Q);
		}
		if (abs(y = 1/(y - (d)a)) > 3*N) {
			return {NP, NQ};
		}
		LP = P; P = NP;
		LQ = Q; Q = NQ;
	}
}

ll crt(ll a, ll m, ll b, ll n) {
	if (n > m) swap(a, b), swap(m, n);
	ll x, y, g = euclid(m, n, x, y);
	assert((a - b) % g == 0);
	x = (b - a) % n * x % n / g * m + a;
	return x < 0 ? x + m*n/g : x;
}

const int LIM = 5'000'000;
bitset<LIM> isprime;
vi eratosthenesSieve(int lim) {
	isprime.set(); isprime[0] = isprime[1] = 0;
	for (int i = 4; i < lim; i += 2) isprime[i] = 0;
	for (int i = 3; i*i < lim; i += 2) if (isprime[i])
		for (int j = i*i; j < lim; j += i*2) isprime[j] = 0;
	vi pr;
	rep(i,2,lim) if (isprime[i]) pr.push_back(i);
	return pr;
}

ll euclid(ll a, ll b, ll &x, ll &y) {
	if (!b) return x = 1, y = 0, a;
	ll d = euclid(b, a % b, y, x);
	return y -= a/b * x, d;
}

ull pollard(ull n) {
	ull x = 0, y = 0, t = 30, prd = 2, i = 1, q;
	auto f = [&](ull x) { return modmul(x, x, n) + i; };
	while (t++ % 40 || __gcd(prd, n) == 1) {
		if (x == y) x = ++i, y = f(x);
		if ((q = modmul(prd, max(x,y) - min(x,y), n))) prd = q;
		x = f(x), y = f(f(y));
	}
	return __gcd(prd, n);
}
vec<ull> factor(ull n) {
	if (n == 1) return {};
	if (isPrime(n)) return {n};
	ull x = pollard(n);
	auto l = factor(x), r = factor(n / x);
	l.insert(l.end(), all(r));
	return l;
}

const int LIM = 1e6;
bitset<LIM> isPrime;
vi eratosthenes() {
	const int S = (int)round(sqrt(LIM)), R = LIM / 2;
	vi pr = {2}, sieve(S+1); pr.reserve(int(LIM/log(LIM)*1.1));
	vec<pii> cp;
	for (int i = 3; i <= S; i += 2) if (!sieve[i]) {
		cp.push_back({i, i * i / 2});
		for (int j = i * i; j <= S; j += 2 * i) sieve[j] = 1;
	}
	for (int L = 1; L <= R; L += S) {
		array<bool, S> block{};
		for (auto &[p, idx] : cp)
			for (int i=idx; i < S+L; idx = (i+=p)) block[i-L] = 1;
		rep(i,0,min(S, R - L))
			if (!block[i]) pr.push_back((L + i) * 2 + 1);
	}
	for (int i : pr) isPrime[i] = 1;
	return pr;
}

struct Frac { ll p, q; };
template <class F>
Frac fracBS(F f, ll N) {
	bool dir = 1, A = 1, B = 1;
	Frac lo{0, 1}, hi{1, 1};
	if (f(lo)) return lo;
	assert(f(hi));
	while (A || B) {
		ll adv = 0, step = 1;
		for (int si = 0; step; (step *= 2) >>= si) {
			adv += step;
			Frac mid{lo.p * adv + hi.p, lo.q * adv + hi.q};
			if (abs(mid.p) > N || mid.q > N || dir == !f(mid)) {
				adv -= step; si = 2;
			}
		}
		hi.p += lo.p * adv;
		hi.q += lo.q * adv;
		dir = !dir;
		swap(lo, hi);
		A = B; B = !!adv;
	}
	return dir ? hi : lo;
}

bool isPrime(ull n) {
	if (n < 2 || n % 6 % 4 != 1) return (n | 1) == 3;
	ull A[] = {2, 325, 9375, 28178, 450775, 9780504, 1795265022},
	    s = __builtin_ctzll(n-1), d = n >> s;
	for (ull a : A) {
		ull p = modpow(a%n, d, n), i = s;
		while (p != 1 && p != n - 1 && a % n && i--)
			p = modmul(p, p, n);
		if (p != n-1 && i != s) return 0;
	}
	return 1;
}

const ll mod = 998244353;
struct Mod {
	ll x;
	Mod(ll x) : x(x % mod) {}
	operator ll() const { return x; }
	Mod operator+(Mod b) { return x + b.x; }
	Mod operator-(Mod b) { return x - b.x + mod; }
	Mod operator*(Mod b) { return x * b.x; }
	Mod operator/(Mod b) { return *this * b.inverse(); }
	Mod pow(ll e) {
		return modpow(x, e);
	}
	Mod inverse() {
		return pow(mod - 2);
	}
};

ll modLog(ll a, ll b, ll m) {
	ll n = (ll) sqrt(m) + 1, e = 1, f = 1, j = 1;
	unordered_map<ll, ll> A;
	while (j <= n && (e = f = e * a % m) != b % m)
		A[e * b % m] = j++;
	if (e == b % m) return j;
	if (__gcd(m, e) == __gcd(m, b))
		rep(i,2,n+2) if (A.count(e = e * f % m))
			return n * i - A[e];
	return -1;
}

ll modpow(ll b, ll e) {
	ll r = 1;
	for (; e; b = b * b % mod, e /= 2)
		if (e & 1) r = r * b % mod;
	return r;
}

ll sqrt(ll a, ll p) {
	a %= p; if (a < 0) a += p;
	if (a == 0) return 0;
	if (modpow(a, (p-1)/2, p) != 1) return -1;
	if (p % 4 == 3) return modpow(a, (p+1)/4, p);
	ll s = p - 1, n = 2;
	int r = 0, m;
	while (s % 2 == 0)
		++r, s /= 2;
	while (modpow(n, (p - 1) / 2, p) != p - 1) ++n;
	ll x = modpow(a, (s + 1) / 2, p);
	ll b = modpow(a, s, p), g = modpow(n, s, p);
	for (;; r = m) {
		ll t = b;
		for (m = 0; m < r && t != 1; ++m)
			t = t * t % p;
		if (m == 0) return x;
		ll gs = modpow(g, 1LL << (r - m - 1), p);
		g = gs * gs % p;
		x = x * gs % p;
		b = b * g % p;
	}
}

using ull = uint64_t;
ull sumsq(ull to) { return to / 2 * ((to-1) | 1); }
ull divsum(ull to, ull c, ull k, ull m) {
	ull res = k / m * sumsq(to) + c / m * to;
	k %= m; c %= m;
	if (!k) return res;
	ull to2 = (to * k + c) / m;
	return res + (to - 1) * to2 - divsum(to2, m-1 - c, m, k);
}
ll modsum(ull to, ll c, ll k, ll m) {
	c = ((c % m) + m) % m;
	k = ((k % m) + m) % m;
	return to * c + k * sumsq(to) - m * divsum(to, c, k, m);
}

using ull = uint64_t;
ull modmul(ull a, ull b, ull M) {
	ll ret = a * b - M * ull(1.L / M * a * b);
	return ret + M * (ret < 0) - M * (ret >= (ll)M);
}
ull modpow(ull b, ull e, ull mod) {
	ull ans = 1;
	for (; e; b = modmul(b, b, mod), e /= 2)
		if (e & 1) ans = modmul(ans, b, mod);
	return ans;
}

const int L = 1e6;
array<int8_t, L> mu;
void calculateMu() {
	mu[1] = 1;
	rep(i,1,L) if (mu[i]) for (int j=2*i; j<L; j+=i) mu[j] -= mu[i];
}

const int LIM = 5000000;
int phi[LIM];
void calculatePhi() {
	rep(i,0,LIM) phi[i] = i&1 ? i : i/2;
	for (int i = 3; i < LIM; i += 2) if (phi[i] == i)
		for (int j = i; j < LIM; j += i) phi[j] -= phi[j] / i;
}

vec<ll> berlekampMassey(vec<ll> s) {
	int n = sz(s), L = 0, m = 0;
	vec<ll> C(n), B(n), T;
	C[0] = B[0] = 1;
	ll b = 1;
	rep(i,0,n) { ++m;
		ll d = s[i] % mod;
		rep(j,1,L+1) d = (d + C[j] * s[i - j]) % mod;
		if (!d) continue;
		T = C; ll coef = d * modpow(b, mod-2) % mod;
		rep(j,m,n) C[j] = (C[j] - coef * B[j - m]) % mod;
		if (2 * L > i) continue;
		L = i + 1 - L; B = T; b = d; m = 0;
	}
	C.resize(L + 1); C.erase(C.begin());
	for (ll& x : C) x = (mod - x) % mod;
	return C;
}

void FST(auto& a, bool inv) {
	for (int n = sz(a), step = 1; step < n; step *= 2) {
		for (int i = 0; i < n; i += 2 * step) rep(j,i,i+step) {
			auto &u = a[j], &v = a[j + step]; pii p =
				inv ? pii{v - u, u} : pii{v, u + v};
			u = p[0], v = p[1];
		}
	}
}
auto conv(auto a, auto b) {
	FST(a, 0); FST(b, 0);
	rep(i,0,sz(a)) a[i] = a[i] * b[i];
	FST(a, 1); return a;
}

double gss(double a, double b, auto f, double eps = 1e-7) {
	const double r = (sqrt(5) - 1) / 2;
	double x1 = b - r * (b - a), x2 = a + r * (b - a);
	double f1 = f(x1), f2 = f(x2);
	while (b - a > eps)
		if (f1 < f2) {
			b = x2; x2 = x1; f2 = f1;
			x1 = b - r * (b - a); f1 = f(x1);
		} else {
			a = x1; x1 = x2; f1 = f2;
			x2 = a + r * (b - a); f2 = f(x2);
		}
	return a;
}

using P = array<double, 2>;
template <class F> pair<double, P> hillClimb(P start, F f) {
	pair<double, P> cur(f(start), start);
	for (double jmp = 1e9; jmp > 1e-20; jmp /= 2) {
		rep(j,0,100) rep(dx,-1,2) rep(dy,-1,2) {
			P p = cur.second;
			p[0] += dx*jmp;
			p[1] += dy*jmp;
			cur = min(cur, make_pair(f(p), p));
		}
	}
	return cur;
}

ll det(vec<vec<ll>>& a) {
	int n = sz(a); ll ans = 1;
	rep(i,0,n) {
		rep(j,i+1,n) {
			while (a[j][i] != 0) {
				ll t = a[i][i] / a[j][i];
				if (t) rep(k,i,n)
					a[i][k] = (a[i][k] - a[j][k] * t) % mod;
				swap(a[i], a[j]);
				ans *= -1;
			}
		}
		ans = ans * a[i][i] % mod;
		if (!ans) return 0;
	}
	return (ans + mod) % mod;
}

template <class F>
double quad(double a, double b, F f, const int n = 1000) {
	double h = (b - a) / 2 / n, v = f(a) + f(b);
	rep(i,1,n*2)
		v += f(a + i*h) * (i&1 ? 4 : 2);
	return v * h / 3;
}

using d = double;
#define S(a,b) (f(a) + 4*f((a+b) / 2) + f(b)) * (b-a) / 6
template <class F>
d rec(F& f, d a, d b, d eps, d S) {
	d c = (a + b) / 2;
	d S1 = S(a, c), S2 = S(c, b), T = S1 + S2;
	if (abs(T - S) <= 15 * eps || b - a < 1e-10)
		return T + (T - S) / 15;
	return rec(f, a, c, eps / 2, S1) + rec(f, c, b, eps / 2, S2);
}
template <class F>
d quad(d a, d b, F f, d eps = 1e-8) {
	return rec(f, a, b, eps, S(a, b));
}

using Poly = vec<ll>;
ll linearRec(Poly S, Poly tr, ll k) {
	int n = sz(tr);
	auto combine = [&](Poly a, Poly b) {
		Poly res(n * 2 + 1);
		rep(i,0,n+1) rep(j,0,n+1)
			res[i + j] = (res[i + j] + a[i] * b[j]) % mod;
		for (int i = 2 * n; i > n; --i) rep(j,0,n)
			res[i - 1 - j] = (res[i - 1 - j] + res[i] * tr[j]) % mod;
		res.resize(n + 1);
		return res;
	};
	Poly pol(n + 1), e(pol);
	pol[0] = e[1] = 1;
	for (++k; k; k /= 2) {
		if (k % 2) pol = combine(pol, e);
		e = combine(e, e);
	}
	ll res = 0;
	rep(i,0,n) res = (res + pol[i + 1] * S[i]) % mod;
	return res;
}

int matInv(vec<vec<ll>>& A) {
	int n = sz(A); vi col(n);
	vec<vec<ll>> tmp(n, vec<ll>(n));
	rep(i,0,n) tmp[i][i] = 1, col[i] = i;
	rep(i,0,n) {
		int r = i, c = i;
		rep(j,i,n) rep(k,i,n) if (A[j][k]) {
			r = j; c = k; goto found;
		}
		return i;
found:
		A[i].swap(A[r]); tmp[i].swap(tmp[r]);
		rep(j,0,n)
			swap(A[j][i], A[j][c]), swap(tmp[j][i], tmp[j][c]);
		swap(col[i], col[c]);
		ll v = modpow(A[i][i], mod - 2);
		rep(j,i+1,n) {
			ll f = A[j][i] * v % mod;
			A[j][i] = 0;
			rep(k,i+1,n) A[j][k] = (A[j][k] - f*A[i][k]) % mod;
			rep(k,0,n) tmp[j][k] = (tmp[j][k] - f*tmp[i][k]) % mod;
		}
		rep(j,i+1,n) A[i][j] = A[i][j] * v % mod;
		rep(j,0,n) tmp[i][j] = tmp[i][j] * v % mod;
		A[i][i] = 1;
	}
	for (int i = n-1; i > 0; --i) rep(j,0,i) {
		ll v = A[j][i];
		rep(k,0,n) tmp[j][k] = (tmp[j][k] - v*tmp[i][k]) % mod;
	}
	rep(i,0,n) rep(j,0,n)
		A[col[i]][col[j]] = tmp[i][j] % mod + (tmp[i][j] < 0)*mod;
	return n;
}

const int LG = 23;
template <class u, class uu, u p, u root>
struct FFT {
	u r[1+(2<<LG)];
	constexpr u m(u a, u b) {
		uu k = uu(a)*b;
		#define op(g) g*(g*p+2)
		k += u(k) * (op(op(op(op(op(-p)))))) * uu(p);
		#undef op
		return u(k>>(8*sizeof(u)));
	}
	constexpr u red(u k, u a) { return a-k*(a>=k); }
	FFT() {
		u k = r[2<<LG] = -p%p, b = root, e = p>>LG;
		for (; e; e /= 2, b = m(b, b)) if (e % 2) k = m(k, b);
		for (int i = (2<<LG) - 1; i >= 0; i--)
			r[i] = red(p, m(r[i+1], k)), i&(i-1) ? 0 : k = m(k, k);
		assert(r[2] != r[3]); assert(r[1] == r[2]);
	}
	vec<ll> cv(const vec<ll>& as, const vec<ll>& bs, u* v) {
		int c = max(sz(as) + sz(bs) - 1, 0), n = 1;
		assert(c <= (1<<LG));
		u h = u(uu(-p)*-p%p), a = m(h, p/2 + 1), x, y;
		while (n < c) n *= 2, h = red(p, m(h, a));
		rep(i,0,n)
			v[i] = i < sz(as) ? u(as[i]) : 0,
			v[i+n] = i < sz(bs) ? u(bs[i]) : 0;
		for (auto s : {v, v + n})
		for (int j = n; j >= 2; j--)
		for (int k = j&-j; k /= 2;) rep(i,j-k,j)
			x = s[i], y = s[i-k],
			s[i-k] = red(2*p, x + y),
			s[i] = m(2*p + y - x, r[3*k-j+i]);
		rep(i,0,n) v[i] = m(v[i], v[i+n]);
		rep(j,2,n+1) for (int k = 1; !(k&j); k *= 2) rep(i,j-k,j)
			x = m(v[i], r[3*k+j-i]),
			y = red(2*p, v[i-k]),
			v[i-k] = x + y, v[i] = 2*p + y - x;
		rep(i,0,c) v[i] = red(p, m(v[i], h));
		return vec<ll>(v, v + c);
	}
};
vec<ll> convSmall(const vec<ll>& as, const vec<ll>& bs) {
	static uint32_t v[2<<LG];
	static FFT<uint32_t, uint64_t, 998244353, 3> fft;
	return fft.cv(as, bs, v);
}
vec<ll> convBig(const vec<ll>& as, const vec<ll>& bs) {
	static uint64_t v[2<<LG];
	static const uint64_t P = (1ull<<62)-(18ull<<32)+1;
	static FFT<uint64_t, __uint128_t, P, 3> fft;
	return fft.cv(as, bs, v);
}
vec<ll> convSunzi(const vec<ll>& v1, const vec<ll>& v2, ll m) {
	const uint64_t inv = 2703402103339935109ull,
		mod1 = (1ull<<62)-(18ull<<32)+1,
		mod2 = (1ull<<62)-(76ull<<32)+1;
	static_assert(__uint128_t(inv)*mod2%mod1 == (-mod1)%mod1);
	static uint64_t v[2<<LG];
	static FFT<uint64_t, __uint128_t, mod1, 3> fft1;
	static FFT<uint64_t, __uint128_t, mod2, 17> fft2;
	auto as = fft1.cv(v1, v2, v), bs = fft2.cv(v1, v2, v);
	rep(i,0,sz(as)) {
		auto d = fft1.m(mod1 + as[i] - bs[i], inv);
		d -= mod1*(d >= mod1); d %= m;
		as[i] = (bs[i] + mod2%m*d)%m;
	}
	return as;
}

using vd = vec<double>;
vd interpolate(vd x, vd y, int n) {
	vd res(n), temp(n);
	rep(k,0,n-1) rep(i,k+1,n)
		y[i] = (y[i] - y[k]) / (x[i] - x[k]);
	double last = 0; temp[0] = 1;
	rep(k,0,n) rep(i,0,n) {
		res[i] += y[k] * temp[i];
		swap(last, temp[i]);
		temp[i] -= last * x[k];
	}
	return res;
}

vec<double> polyRoots(Poly p, double xmin, double xmax) {
	if (sz(p.a) == 2) { return {-p.a[0]/p.a[1]}; }
	vec<double> ret;
	Poly der = p;
	der.diff();
	auto dr = polyRoots(der, xmin, xmax);
	dr.push_back(xmin-1);
	dr.push_back(xmax+1);
	sort(all(dr));
	rep(i,0,sz(dr)-1) {
		double l = dr[i], h = dr[i+1];
		bool sign = p(l) > 0;
		if (sign ^ (p(h) > 0)) {
			rep(it,0,60) {
				double m = (l + h) / 2, f = p(m);
				if ((f <= 0) ^ sign) l = m;
				else h = m;
			}
			ret.push_back((l + h) / 2);
		}
	}
	return ret;
}

struct Poly {
	vec<double> a;
	double operator()(double x) const {
		double val = 0;
		for (int i = sz(a); i--;) (val *= x) += a[i];
		return val;
	}
	void diff() {
		rep(i,1,sz(a)) a[i-1] = i*a[i];
		a.pop_back();
	}
	void divroot(double x0) {
		double b = a.back(), c; a.back() = 0;
		for(int i=sz(a)-1; i--;) c = a[i], a[i] = a[i+1]*x0+b, b=c;
		a.pop_back();
	}
};

